static void f(char**b,int m,int n,int i,int j){if(i<0||j<0||i>=m||j>=n||b[i][j]!='O')return;b[i][j]='#';f(b,m,n,i+1,j);f(b,m,n,i-1,j);f(b,m,n,i,j+1);f(b,m,n,i,j-1);}void solve(char**b,int m,int*cols){if(!m)return;int n=cols[0];for(int i=0;i<m;i++){f(b,m,n,i,0);f(b,m,n,i,n-1);}for(int j=0;j<n;j++){f(b,m,n,0,j);f(b,m,n,m-1,j);}for(int i=0;i<m;i++)for(int j=0;j<n;j++)b[i][j]=b[i][j]=='#'?'O':b[i][j]=='O'?'X':b[i][j];}
